#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include "item.h"
#include "list.h"


struct list {
	int size;
	struct node *head;
};

struct node {
	Item item;
	struct node *next;
};

List newList(){
	List p;
	p = malloc(sizeof(struct list));
	p->size = 0;
	p->head = NULL;
	return p;
}

bool isEmpty(List p){
	return p->size==0;
}

void addHead(List p, Item item){
	struct node * new_node;
	new_node = malloc(sizeof(struct node));
	new_node->item = item;
	new_node->next = p->head;
	p->head = new_node;
	(p->size)++;
}

Item removeHead(List p){
	if(isEmpty(p))
		return NULL;

	struct node *ptr;
	ptr = p->head;
	p->head = ptr->next;
	Item item;
	item = ptr->item;
	free(ptr);
	(p->size)--;
	return item;
}

Item getHead(List p){
	if(isEmpty(p))
		return NULL;
	return p->head->item;
}

int sizeList(List p){
	return p->size;
}

void printList(List p){
	struct node *ptr;
	for(ptr = p->head; ptr!=NULL; ptr=ptr->next){
		outputItem(ptr->item);
	}
}

Item searchList(List list, Item item, int *pos){
	struct node *temp;
	*pos=0;
	for(temp=list->head;temp!=NULL;temp=temp->next,(*pos)++){
		if(cmpItem(temp->item,item)==0)
			return temp->item;
	}
	(*pos)=-1;
	return NULL;
}

Item removeListItem(List list, Item item){
	struct node *p,*prev;
	Item ritorno;
	for(p=list->head;p!=NULL;prev=p,p=p->next){
		if(cmpItem(p->item,item)==0){
			if(p==list->head)
				return removeHead(list);
			else{
			prev->next=p->next;
			ritorno=p->item;
			free(p);
			(list->size)--;
			return ritorno;
			}
		}
	}
	return NULL;
}

Item removeListItemPos(List list, int pos){
	struct node *p,*prev;
	int i=0;
	Item ritorno;
	for(p=list->head;p!=NULL;prev=p,p=p->next,i++)
	{
		if(i==pos)
		{
			if(p==list->head)
				return removeHead(list);
			else{
				prev->next=p->next;
				ritorno=p->item;
				free(p);
				(list->size)--;
				return ritorno;
			}
		}
	}
	return NULL;
}

int addListItem (List list, Item item, int pos){
	int i;
	struct node *p;
	if (pos==0){
		addHead(list,item);
		return 1;
	}
	if (pos > sizeList(list))
		return 0;

	for (p=list->head, i=0; p!=NULL && i<pos-1; i++,p=p->next);

	struct node *new=malloc(sizeof(struct node));
	new->next=p->next;
	p->next= new;
	new->item=item;
	(list->size)++;
	return 1;
}

int addListTail (List list, Item item){
	return addListItem(list,item,sizeList(list));
}

void reverseList(List list){
	struct node *p,*prev,*temp;
	for (p=list->head; p!=NULL; prev=p,p=temp){
		temp=p->next;
		p->next=prev;
	}
	list->head=prev;
}

List cloneList (List list){
	List clone= newList();
	struct node *p;
	for(p=list->head; p!= NULL; p=p->next){
		Item a=cloneItem(p->item);
		addListTail(clone,a);
	}
	return clone;
}

