	s->elements[s->top]=item;
	s->top++;
	return 1;
}

int pop(Stack s){
	if(isEmptyStack(s))
		return 0;
	s->top--;
	return 1;
}

Item top(Stack s){
	if(isEmptyStack(s))
		return NULL;
	return s->elements[s->top-1];
}

